// frontend/src/context/ThemeContext.js
import { createContext, useContext, useState, useEffect } from 'react';

const ThemeContext = createContext({ theme: 'dark', setTheme: () => {} });

export const THEMES = {
  dark: {
    label: 'Dark',
    icon:  'moon',
    vars: {
      '--bv-bg':     '#0d1117',
      '--bv-bg2':    '#161b22',
      '--bv-bg3':    '#1c2128',
      '--bv-bg4':    '#21262d',
      '--bv-bd':     '#30363d',
      '--bv-bd2':    '#444c56',
      '--bv-txt':    '#e6edf3',
      '--bv-txt2':   '#8b949e',
      '--bv-txt3':   '#6e7681',
      '--bv-blue':   '#58a6ff',
      '--bv-green':  '#3fb950',
      '--bv-red':    '#f85149',
      '--bv-amber':  '#e3b341',
      '--bv-cyan':   '#39d0d8',
      '--bv-purple': '#bc8cff',
    }
  },
  light: {
    label: 'Light',
    icon:  'sun',
    vars: {
      '--bv-bg':     '#f6f8fa',
      '--bv-bg2':    '#ffffff',
      '--bv-bg3':    '#f0f2f4',
      '--bv-bg4':    '#e6e9ec',
      '--bv-bd':     '#d0d7de',
      '--bv-bd2':    '#afb8c1',
      '--bv-txt':    '#1f2328',
      '--bv-txt2':   '#57606a',
      '--bv-txt3':   '#848d97',
      '--bv-blue':   '#0969da',
      '--bv-green':  '#1a7f37',
      '--bv-red':    '#d1242f',
      '--bv-amber':  '#9a6700',
      '--bv-cyan':   '#0ca4a5',
      '--bv-purple': '#8250df',
    }
  },
  white: {
    label: 'White',
    icon:  'brightness',
    vars: {
      '--bv-bg':     '#ffffff',
      '--bv-bg2':    '#ffffff',
      '--bv-bg3':    '#f8f9fa',
      '--bv-bg4':    '#f1f3f4',
      '--bv-bd':     '#e1e4e8',
      '--bv-bd2':    '#c9cdd2',
      '--bv-txt':    '#1a1a2e',
      '--bv-txt2':   '#4a5568',
      '--bv-txt3':   '#718096',
      '--bv-blue':   '#185FA5',
      '--bv-green':  '#276749',
      '--bv-red':    '#9b2335',
      '--bv-amber':  '#7b5800',
      '--bv-cyan':   '#0d7d7e',
      '--bv-purple': '#6b46c1',
    }
  }
};

function applyTheme(name) {
  const theme = THEMES[name];
  if (!theme) return;
  const root = document.documentElement;
  Object.entries(theme.vars).forEach(([k, v]) => root.style.setProperty(k, v));
  // Also apply body background
  document.body.style.background = theme.vars['--bv-bg'];
  document.body.style.color      = theme.vars['--bv-txt'];
}

export function ThemeProvider({ children }) {
  const [theme, setThemeState] = useState(() => {
    return localStorage.getItem('bv_theme') || 'dark';
  });

  function setTheme(name) {
    setThemeState(name);
    localStorage.setItem('bv_theme', name);
    applyTheme(name);
  }

  useEffect(() => { applyTheme(theme); }, [theme]);

  return (
    <ThemeContext.Provider value={{ theme, setTheme, themes: THEMES }}>
      {children}
    </ThemeContext.Provider>
  );
}

export const useTheme = () => useContext(ThemeContext);
